'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2),ar=n=>Number(n).toLocaleString('ar-SA'),letters=['أ','ب','ج','د'];
const icons={home:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',students:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-4a6 6 0 0112 0v4M16 5a3 3 0 010 6m2 3a5 5 0 013 5"/>',exams:'<rect x="5" y="3" width="14" height="19" rx="2"/><path d="M9 7h6M9 11h6m-6 4h3"/>',scan:'<path d="M3 8V3h5m8 0h5v5M3 16v5h5m8 0h5v-5M2 12h20"/><path d="m8 12 3 3 5-6"/>',key:'<circle cx="8" cy="8" r="5"/><path d="m12 12 9 9m-4-4 3-3m-6 0 3-3"/>',results:'<path d="M4 20V10m8 10V4m8 16v-7M2 22h20"/>'};
const navs=[['home','نظرة عامة'],['students','الطلاب والمجموعات'],['exams','الاختبارات'],['scan','التصحيح الذكي'],['key','مفاتيح الإجابة'],['results','النتائج والتقارير']];
let db={students:[],groups:['الأول المتوسط — أ','الأول المتوسط — ب'],exams:[],results:[]};
let page='home',currentExam=null,currentResult=null,scanQueue=[],scanIndex=0,scanState=null,manualCorners=[],isManual=false,saveTimer;
function save(){if(window.WaraqaCloud)return window.WaraqaCloud.changed();try{localStorage.setItem('waraqa-v1',JSON.stringify(db))}catch{toast('تعذر الحفظ: مساحة الجهاز ممتلئة. صدّر نسخة احتياطية.')}}
const idb=new Promise((resolve,reject)=>{const r=indexedDB.open('waraqa-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
async function localFilePut(key,value){const d=await idb;return new Promise((res,rej)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').put(value,key);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}async function localFileGet(key){const d=await idb;return new Promise((res,rej)=>{const r=d.transaction('files').objectStore('files').get(key);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function filePut(key,value){return window.WaraqaCloud?window.WaraqaCloud.filePut(key,value):localFilePut(key,value)}
async function fileGet(key){return window.WaraqaCloud?window.WaraqaCloud.fileGet(key):localFileGet(key)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(saveTimer);saveTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300)}
function modal(title,html){stopDictation();$('#modal-body').innerHTML=`<div class="modal-head"><h2>${title}</h2><button onclick="closeModal()" aria-label="إغلاق">×</button></div><div class="modal-content">${html}</div>`;$('#modal').showModal()}function closeModal(){$('#modal').close();$('#modal').classList.remove('paper-preview-modal')}
function route(){page=location.hash.slice(1)||'home';if(!navs.some(n=>n[0]===page))page='home';$('#nav').innerHTML=navs.map(([k,t])=>`<a href="#${k}" class="${k===page?'active':''}" title="${t}"><svg viewBox="0 0 24 24">${icons[k]}</svg><span>${t}</span></a>`).join('');$('#breadcrumb').textContent=navs.find(n=>n[0]===page)[1];render()}
function render(){if(typeof stopPaperCamera==='function')stopPaperCamera();stopDictation();const a=$('#app');a.style.animation='none';void a.offsetWidth;a.style.animation='enter .3s';({home,students,exams,scan,key:keys,results}[page])()}
function head(title,sub,actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p class="sub">${esc(sub)}</p></div><div class="actions">${actions}</div></div>`}function empty(title,desc,button=''){return `<div class="empty"><div class="empty-symbol">▤</div><h3>${title}</h3><p>${desc}</p>${button}</div>`}function btn(text,click,cl=''){return `<button type="button" class="btn ${cl}" onclick="${click}">${text}</button>`}function options(items,value){return items.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}function examOptions(){return options(db.exams.map(e=>[e.id,e.title]),currentExam)}function getExam(){return db.exams.find(e=>e.id===currentExam)}function total(e){return e.questions.reduce((a,q)=>a+Number(q.points),0)}function score(r){const e=db.exams.find(e=>e.id===r.exam);if(!e)return 0;return (r.snapshot?.paperVersion>=6?Math.min(essayMaximum(e),Math.max(0,Number(r.essay?.[-1]||0))):0)+e.questions.reduce((a,q,i)=>a+(q.type==='essay'?(r.snapshot?.paperVersion>=6?0:Math.min(q.points,Math.max(0,Number(r.essay?.[i]||0)))):(q.answer!==null&&r.answers[i]===q.answer?Number(q.points):0)),0)}
function home(){let avg=db.results.length?Math.round(db.results.reduce((a,r)=>{const e=resultExam(r);return a+(e&&total(e)?100*score(r)/total(e):0)},0)/db.results.length):0;$('#app').innerHTML=head('كل ورقة، بداية إنجاز.','أهلًا بك في مساحتك. اختبارات أذكى، ووقت أكثر لطلابك.',btn('＋ إنشاء اختبار','newExam()'))+`<section class="hero"><div class="hero-copy"><div class="eyebrow">فكرة مختلفة. تجربة أبسط.</div><h2>السؤال وإجابته في ورقة واحدة.<br>والتصحيح؟ أصبح أسهل.</h2><p>أنشئ اختبارك، واطبعه، ثم ارفع أوراق طلابك. علامات الزوايا تساعد على قراءة التظليل في مكانه الصحيح.</p><div class="actions">${btn('ابدأ باختبارك الأول ←','newExam()','lime')}${btn('استكشف نموذج الورقة','demoPaper()','light')}</div></div><div class="hero-art"><div class="orbit"></div><div class="mini-paper">${[0,1,2].map((x)=>`<div class="mini-line"></div><div class="mini-bubbles">${letters.map((l,i)=>`<i class="${x===i?'on':''}">${l}</i>`).join('')}</div>`).join('')}</div><span class="float-check">✓</span><div class="float-tag">◈ الأسئلة + التظليل = ورقة واحدة</div></div></section><section class="stats">${[['♧','إجمالي الطلاب',db.students.length,`${ar(db.groups.length)} مجموعات دراسية`],['▤','الاختبارات',db.exams.length,'كل اختبار يبدأ بفكرة'],['⌗','الأوراق المصححة',db.results.length,'نتائج قابلة للمراجعة'],['◴','متوسط النتائج',db.results.length?ar(avg)+'٪':'—','من أوراقك المحفوظة']].map(s=>`<div class="stat"><span class="stat-icon">${s[0]}</span><div><small>${s[1]}</small><strong>${typeof s[2]==='number'?ar(s[2]):s[2]}</strong><em>${s[3]}</em></div></div>`).join('')}</section><div class="grid-main"><section class="panel"><div class="panel-title"><h2>اختباراتك الأخيرة <span class="badge-number">${ar(db.exams.length)}</span></h2><a class="text-link" href="#exams">عرض الكل ←</a></div>${db.exams.length?db.exams.slice(-3).reverse().map(examRow).join(''):empty('مساحة لأفكارك القادمة','أنشئ أول اختبار وابدأ رحلة التصحيح.',btn('＋ إنشاء اختبار','newExam()','small light'))}</section><section class="panel"><div class="panel-title"><h2>خطوتك التالية</h2><span class="tag gray">وصول سريع</span></div>${[['♧','أضف طلابك','فرد واحد أو مجموعة كاملة','studentModal()'],['▤','صمّم ورقة الاختبار','أسئلة وتظليل في الصفحة نفسها','newExam()'],['⌗','ابدأ التصحيح','من صورة، ملف PDF، أو الكاميرا',"location.hash='scan'"]].map(s=>`<button class="quick" onclick="${s[3]}"><span>${s[0]}</span><div><b>${s[1]}</b><small>${s[2]}</small></div><span class="arrow">←</span></button>`).join('')}</section></div><div class="tip"><span>✧</span><div><strong>ورقة واحدة، احتمالات أكثر.</strong><br>اطبع بالحجم الفعلي، واحتفظ بمربعات الزوايا الأربعة داخل الصورة. القراءات غير الواضحة تبقى للمراجعة قبل اعتماد النتيجة.</div></div>`}
function studentModal(bulk=false,id=null){resetStudentImport();const s=db.students.find(s=>s.id===id)||{};modal(bulk?'إضافة مجموعة طلاب':id?'تعديل بيانات الطالب':'إضافة طالب',`<form onsubmit="event.preventDefault();submitStudents('${id||''}',${bulk})"><div class="section-tabs"><button type="button" class="${!bulk?'active':''}" onclick="closeModal();studentModal(false)">فرد</button><button type="button" class="${bulk?'active':''}" onclick="closeModal();studentModal(true)">مجموعة</button></div>${bulk?`<p class="note">اختر ملف Excel أو Numbers مباشرة، أو انسخ عمودي الاسم والرقم والصقهما أدناه. يمكنك تحديد الأعمدة وورقة العمل قبل الحفظ.</p><label class="field">استيراد Excel / Numbers / CSV<input id="student-import-file" type="file" accept=".xlsx,.xls,.numbers,.csv,.tsv,.txt,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel,application/vnd.apple.numbers,application/x-iwork-numbers-sffnumbers,text/csv,text/tab-separated-values" onchange="readStudentFile(this.files[0])"></label><label class="field">أو الصق جدول الطلاب هنا<textarea id="student-names" oninput="previewPastedStudents()" placeholder="اسم الطالب&#9;رقم الطالب
أحمد محمد&#9;001001
خالد علي&#9;001002"></textarea></label><div id="student-import-controls"></div><div id="student-import-preview" aria-live="polite"></div>`:`<label class="field">اسم الطالب<input id="student-name" value="${esc(s.name||'')}" maxlength="100" required></label><label class="field">الرقم الدراسي<input id="student-number" value="${esc(s.number||'')}" maxlength="40" required></label>`}<label class="field">المجموعة<select id="student-group" onchange="if(studentImportState?.config)renderStudentImport()">${options(db.groups.map(g=>[g,g]),s.group)}</select></label><label class="field">أو إنشاء مجموعة جديدة<input id="new-group" oninput="if(studentImportState?.config)renderStudentImport()" placeholder="مثل: ثاني متوسط — أ" maxlength="80"></label><button class="btn" type="submit">حفظ الطلاب</button></form>`)}

function submitStudents(id,bulk){if(bulk)return commitStudentImport();const g=$('#new-group').value.trim()||$('#student-group').value||'بدون مجموعة';let entries=[[$('#student-name').value.trim(),$('#student-number').value.trim()]];if(!entries.length)return toast('أدخل اسم طالب واحد على الأقل');const nums=new Set(db.students.filter(s=>s.id!==id).map(s=>s.number));const added=[];for(const [name,number]of entries){if(!name)return toast('الاسم مطلوب');if(number&&nums.has(number))return toast('الرقم الدراسي مكرر: '+number);let n=number||String(Date.now())+added.length;nums.add(n);added.push({id:id||uid(),name,number:n,group:g})}if(!db.groups.includes(g))db.groups.push(g);db.students=db.students.filter(s=>s.id!==id).concat(added);save();closeModal();render();toast('تم حفظ '+ar(added.length)+' طالب')}
function students(){const filter=window.studentFilter||'';$('#app').innerHTML=head('الطلاب والمجموعات','كل طالب له مكان. نظّم مجموعاتك وابدأ بسهولة.',btn('＋ إضافة طالب','studentModal()')+btn('استيراد مجموعة','studentModal(true)','light'))+`<div class="toolbar"><input placeholder="ابحث بالاسم أو الرقم الدراسي…" aria-label="البحث عن طالب" oninput="filterStudents(this.value)"><select style="width:auto" id="group-filter" onchange="window.studentFilter=this.value;students()"><option value="">جميع المجموعات</option>${options(db.groups.map(g=>[g,g]),filter)}</select>${btn('إدارة المجموعات','groupModal()','light small')}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>الطالب</th><th>الرقم الدراسي</th><th>المجموعة</th><th>الإجراءات</th></tr></thead><tbody id="students-body">${studentRows('',filter)}</tbody></table></div>${!db.students.length?empty('لنبدأ بطلابك','أضف طالبًا أو استورد قائمة الأسماء.'):''}</section>`}function studentRows(search='',group=''){return db.students.filter(s=>(!group||s.group===group)&&(s.name.includes(search)||s.number.includes(search))).map(s=>`<tr><td><span class="avatar">${esc(s.name[0])}</span>${esc(s.name)}</td><td>${esc(s.number)}</td><td><span class="tag gray">${esc(s.group)}</span></td><td><button class="text-link" onclick="studentModal(false,'${s.id}')">تعديل</button> <button class="delete-link" onclick="deleteStudent('${s.id}')">حذف</button></td></tr>`).join('')}function filterStudents(v){$('#students-body').innerHTML=studentRows(v,$('#group-filter').value)}function deleteStudent(id){if(!confirm('حذف الطالب؟ تبقى أوراقه السابقة محفوظة باسمه.'))return;db.students=db.students.filter(s=>s.id!==id);save();students()}function groupModal(){modal('إدارة المجموعات',db.groups.map((g,i)=>`<div class="exam-row"><span>${esc(g)}</span><span class="tag">${ar(db.students.filter(s=>s.group===g).length)} طالب</span><button class="delete-link" onclick="removeGroup(${i})">حذف</button></div>`).join('')+`<form onsubmit="event.preventDefault();addGroup()" class="toolbar" style="margin-top:20px"><input id="group-name" required placeholder="اسم المجموعة الجديدة">${btn('إضافة','addGroup()','small')}</form>`)}function addGroup(){const n=$('#group-name').value.trim();if(n&&!db.groups.includes(n)){db.groups.push(n);save();closeModal();groupModal()}}function removeGroup(i){const g=db.groups[i];if(db.students.some(s=>s.group===g))return toast('انقل الطلاب إلى مجموعة أخرى قبل حذفها');db.groups.splice(i,1);save();closeModal();groupModal()}
function newExam(){examModal()}function examModal(id=null){const e=db.exams.find(x=>x.id===id)||{};modal(id?'معلومات الاختبار':'لنصمّم اختبارًا جديدًا',`<form onsubmit="event.preventDefault();saveExam('${id||''}')"><div class="form-grid"><label class="field wide">عنوان الاختبار<input id="e-title" required maxlength="65" value="${esc(e.title||'')}" placeholder="اختبار الفصل الأول"></label><label class="field">المادة<input id="e-subject" required maxlength="40" value="${esc(e.subject||'')}" placeholder="العلوم"></label><label class="field">الصف / المجموعة<select id="e-group">${options([['','كل المجموعات'],...db.groups.map(g=>[g,g])],e.group)}</select></label><label class="field">التاريخ<input id="e-date" type="date" value="${e.date||new Date().toISOString().slice(0,10)}" required></label><label class="field">المدة بالدقائق<input id="e-duration" type="number" min="1" max="600" value="${e.duration||45}" required></label><label class="field wide">تعليمات الطالب<textarea id="e-notes" maxlength="180" placeholder="ظلّل حرف إجابة واحدة بقلم رصاص…">${esc(e.notes||'ظلّل دائرة إجابة واحدة لكل سؤال. حافظ على نظافة مربعات الزوايا.')}</textarea></label></div><button class="btn" type="submit">${id?'حفظ المعلومات':'إنشاء والانتقال للأسئلة ←'}</button></form>`)}
function saveExam(id){let e=db.exams.find(x=>x.id===id);const data={title:$('#e-title').value.trim(),subject:$('#e-subject').value.trim(),group:$('#e-group').value,date:$('#e-date').value,duration:Number($('#e-duration').value),notes:$('#e-notes').value};if(!data.title||!data.subject)return toast('أكمل العنوان والمادة');if(e)Object.assign(e,data);else{e={...data,id:uid(),questions:[]};db.exams.push(e)}currentExam=e.id;save();closeModal();location.hash='exams';exams()}
function examRow(e){return `<div class="exam-row"><div class="exam-icon">▤</div><div><h3>${esc(e.title)}</h3><small>${esc(e.subject)} · ${ar(e.questions.length)} أسئلة · ${ar(total(e))} درجة</small></div><span class="tag ${e.questions.some(q=>q.answer===null&&q.type!=='essay')?'amber':''}">${e.questions.length?'جاهز للتحرير':'مسودة'}</span><button class="text-link" onclick="openExam('${e.id}')">فتح ←</button></div>`}function openExam(id){currentExam=id;location.hash='exams';exams()}
function exams(){stopDictation();const e=getExam();if(!e){$('#app').innerHTML=head('الاختبارات','من فكرتك إلى ورقة جاهزة للطباعة.',btn('＋ اختبار جديد','newExam()')+questionFileButtons())+`<section class="panel">${db.exams.length?db.exams.slice().reverse().map(examRow).join(''):empty('اختبارك الأول ينتظرك','أضف أسئلة اختيار من متعدد، صح وخطأ، أو أسئلة مقالية.')}</section>`;return}$('#app').innerHTML=head(e.title,`${e.subject} · ${e.duration} دقيقة · ${ar(e.questions.length)} أسئلة · ${ar(total(e))} درجة`,questionFileButtons()+btn('طباعة الورقة','printModal()')+btn('معاينة مكبّرة','showPaperPreview()','light')+btn('معلومات الاختبار',`examModal('${e.id}')`,'light')+btn('كل الاختبارات','currentExam=null;exams()','light'))+`<div class="editor-layout"><div><p class="note voice-help">اضغط أيقونة الميكروفون لإملاء السؤال أو الخيار بالعربية. أوقف الإملاء قبل الانتقال لحقل آخر. قد يستخدم المتصفح خدمة خارجية للتعرّف على الكلام؛ لا تُحفظ ملفات صوتية في ورقة.</p><div class="section-tabs">${btn('＋ اختياري',"addQuestion('mcq')",'light small')}${btn('＋ صح وخطأ',"addQuestion('tf')",'light small')}${btn('＋ مقالي',"addQuestion('essay')",'light small')}</div>${e.questions.map((q,i)=>`<div class="question-card"><div class="q-head"><span class="q-num">السؤال ${ar(questionNumber(e,i))} · ${{mcq:'اختيار من متعدد',tf:'صح وخطأ',essay:'مقالي'}[q.type]}</span><div><button class="text-link" onclick="moveQ(${i},-1)" title="تحريك لأعلى">↑</button><button class="text-link" onclick="moveQ(${i},1)" title="تحريك لأسفل">↓</button><button class="delete-link" onclick="deleteQ(${i})">حذف</button></div></div><div class="question-voice-field"><label class="field" for="voice-input-${voiceKey(q.id)}">نص السؤال (حتى ٨٠ حرفًا لضمان وضوح الطباعة)</label><div class="voice-input-row"><input id="voice-input-${voiceKey(q.id)}" maxlength="80" value="${esc(q.text)}" oninput="stopDictation();updateQ(${i},'text',this.value)" placeholder="اكتب سؤالك هنا أو استخدم الميكروفون…">${dictationButton(e,q,i)}</div>${voiceStatus(q.id)}</div>${q.type==='essay'?'<div class="note">يصحّح المعلم جميع المقاليات يدويًا ثم يظلّل مجموع درجاتها مرة واحدة في أعلى الورقة. الفقاعات ١–١٥، والصفر أو المجموع الأعلى من ١٥ يُرصد يدويًا في المراجعة.</div>':`<div class="q-options">${q.options.map((o,j)=>`<label><button title="تعيين إجابة صحيحة" class="bubble ${q.answer===j?'selected':''}" onclick="setAnswer(${i},${j})">${q.type==='tf'?(j?'خ':'ص'):letters[j]}</button>${q.type==='tf'?esc(o):`<div class="option-voice-field"><div class="voice-input-row"><input id="voice-input-${voiceKey(q.id,j)}" maxlength="24" aria-label="الخيار ${letters[j]}" value="${esc(o)}" oninput="stopDictation();updateOption(${i},${j},this.value)" placeholder="الخيار ${letters[j]}">${dictationButton(e,q,i,j)}</div>${voiceStatus(q.id,j)}</div>`}</label>`).join('')}</div>`}<div class="q-meta">الدرجة <input aria-label="درجة السؤال" type="number" min="${q.type==='essay'?1:0.25}" max="${q.type==='essay'?15:100}" step="${q.type==='essay'?1:0.25}" value="${q.points}" onchange="updatePoints(${i},this)"><span>${q.type==='essay'?'تصحيح يدوي ثم قراءة فقاعة الدرجة':q.answer===null?'اختر حرف الإجابة الصحيحة':'✓ مفتاح الإجابة محدد'}</span></div></div>`).join('')||`<section class="panel">${empty('ابدأ بسؤالك الأول','اختر نوع السؤال من الأعلى. تحفظ التعديلات على هذا الجهاز.')}</section>`}</div><div><div class="paper-card"><div style="display:flex;justify-content:space-between;margin-bottom:15px;font-size:12px">معاينة الورقة <span class="tag gray">A4 أفقي</span></div><label class="field">معاينة الصفحة<select id="preview-page" onchange="document.querySelector('#paper-preview').innerHTML=paperSVG(getExam(),Number(this.value))">${options(paperPlan(e).map((_,i)=>[String(i),'صفحة '+ar(i+1)]),'0')}</select></label><div id="paper-preview">${paperSVG(e,0)}</div><p class="note">${ar(pageCount(e))} صفحة · A4 أفقي · تتتابع الاختيارات ثم الصح والخطأ ثم المقالي من اليمين إلى اليسار.</p></div><div class="tip"><span>⌗</span><div><strong>السؤال والتظليل معًا</strong><br>مربعات الزوايا تحدد موضع الإجابات. النموذج الجديد A4 أفقي، بخط أكبر للأسئلة والخيارات. يوزّع النصوص دون تصغيرها؛ عند الحاجة تُضاف صفحة. اطبع أفقيًا بحجم ١٠٠٪.</div></div><p class="note">إعادة ترتيب الأسئلة بعد طباعة الاختبار تستلزم إعادة طباعته. النتائج تحفظ نسخة الأسئلة ومفتاحها وقت التصحيح.</p>${btn('حذف الاختبار',`deleteExam('${e.id}')`,'danger small')}</div></div>`}
function addQuestion(type){const e=getExam();e.questions.push({id:uid(),type,text:'',options:type==='mcq'?['','','','']:type==='tf'?['صح','خطأ']:[],answer:null,points:type==='essay'?15:1});save();exams()}function updateQ(i,k,v){getExam().questions[i][k]=v;save();updatePreview()}function updateOption(i,j,v){getExam().questions[i].options[j]=v;save();updatePreview()}function updatePoints(i,input){const v=Number(input.value);if(getExam().questions[i].type==='essay'&&(!Number.isInteger(v)||v<1||v>15)){input.value=getExam().questions[i].points;return toast('درجة المقالي عدد صحيح من ١ إلى ١٥')}if(!Number.isFinite(v)||v<=0||v>100){input.value=getExam().questions[i].points;return toast('الدرجة بين ٠٫٢٥ و١٠٠')}getExam().questions[i].points=v;save();exams()}function setAnswer(i,j){getExam().questions[i].answer=j;save();page==='key'?keys():exams()}function updatePreview(){if($('#paper-preview'))$('#paper-preview').innerHTML=paperSVG(getExam(),Number($('#preview-page')?.value||0))}function deleteQ(i){if(db.results.some(r=>r.exam===currentExam))toast('النتائج السابقة تحتفظ بنسخة الاختبار القديمة');getExam().questions.splice(i,1);save();exams()}function moveQ(i,d){const qs=getExam().questions;if(i+d<0||i+d>=qs.length)return;[qs[i],qs[i+d]]=[qs[i+d],qs[i]];save();exams()}function deleteExam(id){if(!confirm('حذف الاختبار؟ ستبقى النتائج ونسخ أوراقها محفوظة.'))return;db.exams=db.exams.filter(e=>e.id!==id);currentExam=null;save();exams()}
function keys(){$('#app').innerHTML=head('مفاتيح الإجابة','حدّد الإجابة والدرجة لكل سؤال قبل بدء التصحيح.')+`<div class="toolbar"><select onchange="currentExam=this.value;keys()"><option value="">اختر الاختبار</option>${examOptions()}</select></div>`;const e=getExam();if(!e){$('#app').innerHTML+=`<section class="panel">${empty('اختر اختبارًا لإعداد مفتاحه','ستظهر هنا الأسئلة مع خيارات الإجابة والدرجات.')}</section>`;return}$('#app').innerHTML+=`<section class="panel"><div class="panel-title"><h2>${esc(e.title)}</h2><span class="tag">المجموع ${ar(total(e))} درجة</span></div><div class="panel-pad">${e.questions.map((q,i)=>`<div class="review-q"><b>${ar(questionNumber(e,i))}. ${esc(q.text||'سؤال بدون نص')}</b><div class="row">${q.type==='essay'?'<span class="tag amber">تصحيح يدوي ضمن مجموع المقالي الموحد</span>':q.options.map((o,j)=>`<button class="bubble ${q.answer===j?'selected':''}" title="${esc(o)}" onclick="setAnswer(${i},${j})">${q.type==='tf'?(j?'خ':'ص'):letters[j]}</button>`).join('')}<label style="margin-right:auto">الدرجة <input style="width:80px" type="number" min="${q.type==='essay'?1:0.25}" max="${q.type==='essay'?15:100}" step="${q.type==='essay'?1:0.25}" value="${q.points}" onchange="const n=Number(this.value);if(n>0&&n<=100&&(getExam().questions[${i}].type!=='essay'||(Number.isInteger(n)&&n<=15))){getExam().questions[${i}].points=n;save();keys()}"></label></div></div>`).join('')||empty('لا توجد أسئلة','أضف أسئلة من محرر الاختبار.')}</div></section>`}
function legacyPaperSVG(e,p,student=null){const qs=e.questions.slice(p*8,p*8+8);return `<svg xmlns="http://www.w3.org/2000/svg" width="794" height="1123" viewBox="0 0 794 1123" dir="rtl"><rect width="794" height="1123" fill="white"/>${[[32,32],[762,32],[762,1091],[32,1091]].map(([x,y])=>`<rect x="${x-9}" y="${y-9}" width="18" height="18" fill="#000"/>`).join('')}<g fill="#111" font-family="Arial,Tahoma,sans-serif" text-anchor="start" direction="rtl"><text x="735" y="76" font-size="22" font-weight="bold" ${e.title.length>42?'textLength="660" lengthAdjust="spacingAndGlyphs"':''}>${esc(e.title)}</text><text x="735" y="108" font-size="14">${esc(e.subject)} · ${esc(e.group||'جميع المجموعات')} · المدة ${e.duration} دقيقة</text><text x="735" y="141" font-size="14">الطالب: ${esc(student?.name||'.......................................')}　 الرقم: ${esc(student?.number||'................')}</text><text x="735" y="171" font-size="11">${esc(e.notes?.slice(0,100)||'ظلّل دائرة الإجابة الصحيحة.')}</text></g><path d="M59 187H735" stroke="#ccc"/>${qs.map((q,k)=>{const y=218+k*99;return `<g font-family="Arial,Tahoma,sans-serif" fill="#111"><text x="735" y="${y}" text-anchor="start" direction="rtl" font-size="15">${ar(p*8+k+1)}. ${esc(q.text||'نص السؤال')}</text>${q.type==='essay'?`<path d="M80 ${y+37}H715M80 ${y+63}H715" stroke="#ccc" stroke-dasharray="3 3"/>`:q.options.map((o,j)=>`<circle cx="${688-j*170}" cy="${y+40}" r="12" fill="white" stroke="#111" stroke-width="1.3"/><text x="${688-j*170}" y="${y+44}" text-anchor="middle" font-size="12">${q.type==='tf'?(j?'خ':'ص'):letters[j]}</text><text x="${667-j*170}" y="${y+44}" text-anchor="start" direction="rtl" font-size="11">${esc(o)}</text>`).join('')}</g>`}).join('')}<text x="397" y="1060" font-size="10" font-family="Arial" text-anchor="middle" fill="#555">ورقة · ${esc(e.id.slice(0,8))} · صفحة ${p+1} / ${Math.max(1,pageCount(e,1))} · لا تطوِ مربعات الزوايا</text></svg>`}
function paperSVG(e,p,student=null){return polishedPaperSVG(e,p,student)}
function demoPaper(){const e={id:'DEMO0001',title:'اختبار العلوم — نموذج الورقة',subject:'العلوم',group:'الأول المتوسط',duration:30,notes:'ظلّل حرف الإجابة الصحيحة داخل الدائرة.',questions:[{type:'mcq',text:'أي الكواكب أقرب إلى الشمس؟',options:['عطارد','الأرض','المريخ','زحل'],points:1},{type:'tf',text:'تحتاج النباتات إلى الضوء لصنع غذائها.',options:['صح','خطأ'],points:1},{type:'essay',text:'فسّر أهمية المحافظة على الماء.',options:[],points:2}]};modal('نموذج الأسئلة والتظليل',`<div class="paper-card">${paperSVG(e,0)}</div><p class="note">هذا نموذج توضيحي. أنشئ اختبارك ليصبح قابلًا للتصحيح.</p>`)}
function showPaperPreview(){const e=getExam();if(!e)return;modal('معاينة الورقة — A4 أفقي',`<label class="field">الصفحة<select onchange="document.querySelector('#large-paper').innerHTML=paperSVG(getExam(),Number(this.value))">${options(paperPlan(e).map((_,i)=>[String(i),'صفحة '+ar(i+1)]),'0')}</select></label><p class="note" style="margin-bottom:12px">الأسئلة بخط أكبر. على الهاتف مرّر الورقة أفقيًا لرؤية النص بالحجم المعروض، وعند الطباعة اختر A4 أفقي بحجم ١٠٠٪.</p><div class="large-paper-scroll" id="large-paper">${paperSVG(e,0)}</div>`);$('#modal').classList.add('paper-preview-modal')}
function printModal(){const e=getExam();if(!e.questions.length)return toast('أضف سؤالًا واحدًا على الأقل');if(e.questions.some(q=>!q.text.trim()||q.options.some(o=>!o.trim())))return toast('أكمل نصوص الأسئلة والخيارات قبل الطباعة');if(e.questions.some(q=>q.type==='essay'&&(!Number.isInteger(q.points)||q.points<1||q.points>15)))return toast('اضبط درجات الأسئلة المقالية على أعداد صحيحة من ١ إلى ١٥');modal('طباعة أوراق الاختبار',`<label class="field">نسخة مخصصة<select id="print-student"><option value="">ورقة فارغة الاسم</option><option value="all">جميع طلاب ${esc(e.group||'المجموعات')}</option>${options(db.students.filter(s=>!e.group||s.group===e.group).map(s=>[s.id,s.number+' — '+s.name]))}</select></label><div class="callout">النموذج الأفقي بخط أكبر: ${ar(pageCount(e))} صفحة. يوزّع الأسئلة في ثلاثة أعمدة، مع مجموعة واحدة لمجموع المقالي في صف أعلى الورقة وخط أكبر. تستوعب الصفحة ١٥ اختياريًا و١٥ صح وخطأ عندما تسمح أطوال النصوص. إذا زاد العدد أو المساحة تُضاف صفحة بدل تصغير الخط أكثر.<br>اختر A4 والاتجاه الأفقي (Landscape) والحجم الفعلي ١٠٠٪، وأوقف ترويسات المتصفح. لا تغيّر ترتيب الأسئلة بعد الطباعة. عند التصحيح، اختر الطالب ورقم الصفحة لكل صورة.</div>${btn('فتح نافذة الطباعة','printExam()')}`)}
function printExam(){const e=getExam();e.paperVersion=8;save();const v=$('#print-student').value,ss=v==='all'?db.students.filter(s=>!e.group||s.group===e.group):[db.students.find(s=>s.id===v)||null];if(!ss.length)return toast('لا يوجد طلاب في هذه المجموعة');const w=window.open('','_blank');if(!w)return toast('اسمح بفتح نافذة الطباعة');w.document.write(`<!doctype html><html dir="rtl"><head><title>${esc(e.title)}</title><style>@page{size:A4 landscape;margin:0}body{margin:0}svg{width:297mm;height:210mm;display:block;break-after:page}svg:last-child{break-after:auto}</style></head><body>${ss.map(s=>Array.from({length:pageCount(e)},(_,p)=>paperSVG(e,p,s)).join('')).join('')}</body></html>`);w.document.close();w.onload=()=>w.print();closeModal()}
function scan(){if(scanState)return renderScan();$('#app').innerHTML=head('التصحيح الذكي','ورقة الأسئلة نفسها، هي ورقة الإجابة.')+`<div class="steps"><div class="step active"><b>١</b> اختر الاختبار</div><div class="step"><b>٢</b> ارفع الأوراق</div><div class="step"><b>٣</b> راجع القراءة</div><div class="step"><b>٤</b> احفظ النتائج</div></div><div class="scan-layout"><section class="panel panel-pad"><label class="field">الاختبار<select id="scan-exam" onchange="currentExam=this.value;scan()"><option value="">اختر اختبارًا</option>${examOptions()}</select></label><label class="upload-zone"><span class="upload-icon">⌗</span><h3>ارفع أوراقًا كثيرة دفعة واحدة</h3><p>اسحب الصور أو ملف PDF هنا، أو اختر حتى ٢٠٠ ورقة<br>يمكنك تحديد عدة صور أو اختيار مجلد كامل من الكمبيوتر</p><span class="btn light">↑ اختيار الصور أو الملفات</span><input id="upload-files" type="file" multiple accept="image/*,application/pdf" hidden onchange="loadScans(this.files)"><input id="upload-folder" type="file" webkitdirectory directory multiple accept="image/*,application/pdf" hidden onchange="loadScans(this.files)"></label><div class="actions" style="justify-content:center;margin-top:17px"><button class="btn light" onclick="document.getElementById('upload-folder').click()">▣ اختيار مجلد كامل</button><button class="btn" onclick="openPaperCamera(true)">▣ مسح ضوئي</button><button class="btn light" onclick="openPaperCamera()">◎ تصوير تلقائي بالكاميرا</button></div><p class="note">على iPhone اختر عدة صور من تطبيق «الملفات»؛ اختيار المجلد متاح حسب دعم المتصفح. تُعالج الأوراق بالتتابع داخل جهازك، وتراجع كل ورقة قبل حفظها.</p><p class="note">تدعم القراءة نماذج «ورقة» المطبوعة. الصفحات العادية دون علامات وقالب مطابق تحتاج إدخال الإجابات يدويًا.</p></section><div><section class="panel panel-pad"><h2>لأفضل قراءة ممكنة</h2>${[['01','أظهر الزوايا الأربع','صوّر الورقة كاملة فوق سطح متباين اللون.'],['02','ضوء متوازن، وصورة واضحة','تجنّب اللمعان والظلال القوية.'],['03','المعلم صاحب القرار','راجع التظليل الخفيف، الإجابات المزدوجة والأسئلة المقالية.']].map(s=>`<div class="quick"><span style="font:12px Arial">${s[0]}</span><div><b>${s[1]}</b><small>${s[2]}</small></div></div>`).join('')}</section><div class="tip"><span>✧</span><div>القراءة البصرية هنا إصدار تجريبي. لا توجد نسبة دقة مضمونة قبل معايرتها على أوراقك وطابعتك وكاميرا الهاتف.</div></div></div></div>`;const z=$('.upload-zone');z.ondragover=e=>{e.preventDefault();z.style.background='#eaf2df'};z.ondragleave=()=>z.style.background='';z.ondrop=e=>{e.preventDefault();z.style.background='';loadScans(e.dataTransfer.files)}}
async function getPdf(){if(!window.pdfjsLib)await new Promise((res,rej)=>{let s=document.createElement('script');s.src='pdf.min.js';s.onload=res;s.onerror=rej;document.head.appendChild(s)});pdfjsLib.GlobalWorkerOptions.workerSrc='pdf.worker.min.js';return pdfjsLib}
async function loadScans(files){const e=getExam();if(!e||!e.questions.length)return toast('اختر اختبارًا يحتوي على أسئلة أولًا');if(e.questions.some(q=>q.type!=='essay'&&q.answer===null))return toast('أكمل مفتاح الإجابة أولًا');if(!files.length)return;toast('جارٍ فحص الملفات…');const prepared=[],pdfEntries=new Map();try{for(const f of [...files].filter(x=>x.type.startsWith('image/')||x.type==='application/pdf'||/\.pdf$/i.test(x.name))){if(f.size>40*1024*1024)throw Error('الحد الأقصى لكل صورة أو ملف ٤٠ ميغابايت');if(f.type==='application/pdf'||/\.pdf$/i.test(f.name)){const lib=await getPdf(),doc=await lib.getDocument({data:await f.arrayBuffer()}).promise;if(doc.numPages>200)throw Error('الحد الأقصى ٢٠٠ صفحة في ملف PDF واحد');const entry={file:f,doc,remaining:doc.numPages};pdfEntries.set(f.name,entry);for(let p=1;p<=doc.numPages;p++)prepared.push({name:f.name+' — '+p,page:p,pdf:entry})}else prepared.push({name:f.webkitRelativePath||f.name,file:f})}if(!prepared.length)throw Error('لم أجد صورًا أو ملفات PDF في الاختيار');if(prepared.length>200)throw Error('الحد الأقصى ٢٠٠ ورقة في الدفعة الواحدة. قسّم الباقي إلى دفعة أخرى.');scanQueue=prepared;scanIndex=0;await openScan()}catch(err){for(const entry of pdfEntries.values())try{await entry.doc.destroy()}catch{}toast('تعذر تجهيز الدفعة: '+err.message)}}
async function openScan(){try{const item=scanQueue[scanIndex];let sourceCanvas=null,img=null,objectUrl=null;if(item.pdf){const pg=await item.pdf.doc.getPage(item.page),vp=pg.getViewport({scale:Math.min(2,1800/Math.max(pg.view[2],pg.view[3]))});sourceCanvas=document.createElement('canvas');sourceCanvas.width=Math.round(vp.width);sourceCanvas.height=Math.round(vp.height);await pg.render({canvasContext:sourceCanvas.getContext('2d'),viewport:vp}).promise;item.pdf.remaining--;if(!item.pdf.remaining){await item.pdf.doc.destroy();item.pdf.doc=null}}else if(item.file){objectUrl=URL.createObjectURL(item.file);img=await imageLoad(objectUrl);URL.revokeObjectURL(objectUrl);objectUrl=null}else img=await imageLoad(item.url);const width=sourceCanvas?.width||img.width,height=sourceCanvas?.height||img.height,factor=Math.min(1,1800/Math.max(width,height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(width*factor));c.height=Math.max(1,Math.round(height*factor));const ctx=c.getContext('2d');if(sourceCanvas)ctx.drawImage(sourceCanvas,0,0,c.width,c.height);else ctx.drawImage(img,0,0,c.width,c.height);let oriented=typeof orientScanCanvas==='function'?orientScanCanvas(c,getExam(),8):c;const orientationReady=oriented.scanOrientation?.confident!==false;if(item.documentScan&&orientationReady&&typeof rectifyDocumentCanvas==='function')oriented=rectifyDocumentCanvas(oriented,8);scanState={url:oriented.toDataURL('image/jpeg',.93),canvas:oriented,orientationReady,showOverlay:!!item.cameraScan,documentScan:!!item.documentScan,name:item.name,exam:currentExam,student:'',identityStatus:'جارٍ قراءة رقم الطالب تلقائيًا…',p:0,answers:{},essay:{},flags:{},corners:null,version:8};manualCorners=[];isManual=false;detectAndRead();renderScan();if(typeof identifyScanStudent==='function')identifyScanStudent(scanState)}catch(e){toast(/[\u0600-\u06ff]/.test(e?.message||'')?e.message:'تعذر فتح الصورة. استخدم JPEG أو PNG.')}}
function imageLoad(src){return new Promise((res,rej)=>{let im=new Image();im.onload=()=>res(im);im.onerror=rej;im.src=src})}
function findMarkers(c){const temp=document.createElement('canvas'),k=Math.min(1,900/Math.max(c.width,c.height));temp.width=Math.round(c.width*k);temp.height=Math.round(c.height*k);const ctx=temp.getContext('2d',{willReadFrequently:true});ctx.drawImage(c,0,0,temp.width,temp.height);const w=temp.width,h=temp.height,d=ctx.getImageData(0,0,w,h).data,seen=new Uint8Array(w*h),comps=[];for(let n=0;n<w*h;n++){if(seen[n]||d[n*4]+d[n*4+1]+d[n*4+2]>290)continue;const stack=[n];seen[n]=1;let area=0,minx=w,maxx=0,miny=h,maxy=0;while(stack.length){const a=stack.pop(),x=a%w,y=Math.floor(a/w);area++;minx=Math.min(minx,x);maxx=Math.max(maxx,x);miny=Math.min(miny,y);maxy=Math.max(maxy,y);for(const b of [x>0?a-1:-1,x<w-1?a+1:-1,y>0?a-w:-1,y<h-1?a+w:-1])if(b>=0&&!seen[b]&&d[b*4]+d[b*4+1]+d[b*4+2]<=290){seen[b]=1;stack.push(b)}}const bw=maxx-minx+1,bh=maxy-miny+1;if(area>18&&bw>4&&bh>4&&bw/bh>.45&&bw/bh<2.2&&area/(bw*bh)>.64&&bw<w*.09&&bh<h*.09)comps.push({x:(minx+maxx)/2,y:(miny+maxy)/2,area})}if(comps.length<4)return null;const pool=comps.slice().sort((a,b)=>b.area-a.area).slice(0,Math.min(32,comps.length)),minx=Math.min(...pool.map(p=>p.x)),maxx=Math.max(...pool.map(p=>p.x)),miny=Math.min(...pool.map(p=>p.y)),maxy=Math.max(...pool.map(p=>p.y));if(maxx-minx<w*.12||maxy-miny<h*.12)return null;const targets=[[minx,miny],[maxx,miny],[maxx,maxy],[minx,maxy]],used=new Set(),out=[];for(const [tx,ty] of targets){const candidates=pool.map((p,i)=>({p,i,dist:((p.x-tx)/Math.max(1,maxx-minx))**2+((p.y-ty)/Math.max(1,maxy-miny))**2})).filter(v=>!used.has(v.i)).sort((a,b)=>a.dist-b.dist);if(!candidates.length||candidates[0].dist>.19)return null;used.add(candidates[0].i);out.push({x:candidates[0].p.x/k,y:candidates[0].p.y/k})}return out}
function homography(points,version=2){const src=paperGeometry(version).markers,A=[];for(let i=0;i<4;i++){const [x,y]=src[i],{x:u,y:v}=points[i];A.push([x,y,1,0,0,0,-u*x,-u*y,u],[0,0,0,x,y,1,-v*x,-v*y,v])}for(let i=0;i<8;i++){let pivot=i;for(let j=i+1;j<8;j++)if(Math.abs(A[j][i])>Math.abs(A[pivot][i]))pivot=j;[A[i],A[pivot]]=[A[pivot],A[i]];if(Math.abs(A[i][i])<1e-9)throw Error('الزوايا غير صالحة');const div=A[i][i];for(let j=i;j<9;j++)A[i][j]/=div;for(let r=0;r<8;r++)if(r!==i){const t=A[r][i];for(let j=i;j<9;j++)A[r][j]-=t*A[i][j]}}const v=A.map(r=>r[8]);return(x,y)=>{const den=v[6]*x+v[7]*y+1;return{x:(v[0]*x+v[1]*y+v[2])/den,y:(v[3]*x+v[4]*y+v[5])/den}}}
function detectAndRead(){
 const s=scanState,e=getExam(),plan=scanPlan(s,e);s.corners=s.corners||findMarkers(s.canvas);s.answers={};s.essay={};s.flags={};s.readings={};s.bubbleRegistration=null;
 for(const v of plan.items)if(v.q.type==='essay')s.essay[v.i]=null;
 if(s.orientationReady===false){plan.items.forEach(v=>s.flags[v.i]='اتجاه الورقة غير مؤكد — أدر الصورة حتى يصبح عنوان الاختبار في الأعلى');return}
 if(!s.corners){plan.items.forEach(v=>s.flags[v.i]='لم تُحدد الزوايا — أدخل الإجابة أو اضبط الزوايا');return}
 try{const map=homography(s.corners,s.version||8),c=s.canvas,w=c.width,h=c.height,d=c.getContext('2d',{willReadFrequently:true}).getImageData(0,0,w,h).data;
 if(typeof registerBubbleRings==='function')s.bubbleRegistration=registerBubbleRings(c,map,plan);
 let activeMap=map;const pix=(x,y)=>{const pt=activeMap(x,y),a=Math.round(pt.x),b=Math.round(pt.y);if(a<0||b<0||a>=w||b>=h)return 255;const n=(b*w+a)*4;return .299*d[n]+.587*d[n+1]+.114*d[n+2]};
 for(const v of plan.items){const {q,i,bubbles}=v;if(!bubbles.length){s.flags[i]='نموذج قديم: أدخل درجة المقال يدويًا';continue}
 const scores=bubbles.map(b=>{activeMap=typeof bubblePointMap==='function'?bubblePointMap(s,map,i,b):map;const inner=[];let bg=0,nb=0;for(let dx=-Math.ceil(b.r*1.4);dx<=b.r*1.4;dx++)for(let dy=-Math.ceil(b.r*1.4);dy<=b.r*1.4;dy++){const r=Math.hypot(dx,dy)/b.r;if(r>=.3&&r<=.68)inner.push(pix(b.x+dx,b.y+dy));else if(r>=1.18&&r<=1.36){bg+=pix(b.x+dx,b.y+dy);nb++}}inner.sort((a,b)=>a-b);const tone=inner[Math.floor(inner.length*.65)];return Math.max(0,(bg/nb-tone)/Math.max(70,bg/nb))});
 s.readings[i]=scores;const ranked=scores.map((n,j)=>({n,j})).sort((a,b)=>b.n-a.n),first=ranked[0],second=ranked[1]||{n:0};let value=null;
 if(first.n<.08)s.flags[i]=q.type==='essay'?'لم تُظلّل درجة المقال — يلزم رصدها':'فارغ أو تظليل شديد الخفة';
 else if(second.n>.15&&second.n>first.n*.58)s.flags[i]=q.type==='essay'?'أكثر من درجة مظللة — اختر الدرجة الصحيحة':'تظليل متعدد أو ملتبس';
 else{value=bubbles[first.j].value;s.flags[i]=first.n<.3||first.n-second.n<.16?'تظليل خفيف — تحقق بصريًا':'تحقق من مطابقة القراءة للورقة'}
 if(s.bubbleRegistration&&bubbles.some(b=>!s.bubbleRegistration.offsets[i+':'+b.value]?.reliable)){value=null;s.flags[i]='تعذر مطابقة حلقات الإجابة بوضوح — أعد التصوير أو راجع يدويًا'}
 if(q.type==='essay'){if(value!==null&&value>q.points){s.flags[i]='الدرجة المظللة أعلى من الدرجة المخصصة — راجعها';value=null}s.essay[i]=value}else s.answers[i]=value;
 }
 }catch{ s.corners=null;toast('تعذر ضبط الصفحة، حدّد الزوايا يدويًا')}
}
function essayScanControl(s,v){const {q,i,bubbles}=v;return `<div class="essay-grade-options">${Array.from({length:Math.min(15,q.points)+1},(_,n)=>`<button type="button" class="bubble ${s.essay[i]===n?'selected':''}" ${n>q.points?'disabled':''} aria-label="درجة ${n}" onclick="scanState.essay[${i}]=${n};renderScan()">${ar(n)}</button>`).join('')}</div>${s.version>=6?`<label class="field">مجموع المقالي (٠–${ar(q.points)})<input type="number" min="0" max="${q.points}" step="1" value="${s.essay[i]??''}" onchange="const n=Number(this.value);if(this.value!==''&&Number.isInteger(n)&&n>=0&&n<=${q.points}){scanState.essay[${i}]=n;renderScan()}"></label>`:''}<button class="text-link" onclick="scanState.essay[${i}]=null;renderScan()">إلغاء رصد الدرجة</button><p class="note">درجة المقال المقروءة: <strong>${s.essay[i]===null||s.essay[i]===undefined?'غير مرصودة':ar(s.essay[i])}</strong> / ${ar(q.points)} — يظلّل المعلم الدرجة بعد التصحيح اليدوي.${s.version>=4?' الفقاعات ١–١٥ في أعلى الورقة؛ اختر ٠ يدويًا عند رصد درجة صفرية.':''}</p>`}
function renderScan(){const s=scanState,e=db.exams.find(e=>e.id===s.exam);if(!e){scanState=null;return scan()}currentExam=e.id;const plan=scanPlan(s,e);$('#app').innerHTML=head('مراجعة ورقة الطالب',`${s.name} · ملف ${ar(scanIndex+1)} من ${ar(scanQueue.length)} `,btn('إلغاء','cancelScan()','light'))+scanStatusLegend()+`<div class="callout">يُقرأ رقم الطالب تلقائيًا من الورقة لعرض اسمه. تحقق من الطالب والقالب قبل اعتماد النتيجة. درجة المقال تُقرأ من فقاعة المعلم وتُضاف إلى الدرجة الكلية بعد المراجعة.${!s.corners?' لم يُعثر على المربعات الأربعة تلقائيًا.':''}</div><div class="review-layout"><section><div class="panel panel-pad"><div class="actions" style="margin-bottom:12px">${btn('تحديد الزوايا يدويًا','beginCorners()','light small')}${btn('تدوير ٩٠°','rotateScan()','light small')}${btn(s.showOverlay?'إخفاء مواضع القراءة':'إظهار مواضع القراءة','scanState.showOverlay=!scanState.showOverlay;drawOverlay();renderScan()','light small')}</div><p id="corner-hint" class="note" style="margin-bottom:10px">${s.orientationReady===false?'اتجاه الورقة غير مؤكد؛ أدر الصورة حتى يصبح عنوان الاختبار في الأعلى.':s.corners?'تم ضبط الزوايا. صورة نظيفة؛ يمكنك إظهار مواضع القراءة للمراجعة.':'انقر تحديد الزوايا أو أعد المسح الضوئي.'}</p><div class="scan-image-wrap" style="position:relative"><img id="scan-img" class="scan-preview" alt="ورقة الطالب المرفوعة" src="${s.url}" onclick="pickCorner(event)"><canvas id="scan-overlay" style="position:absolute;inset:0;width:100%;height:100%;pointer-events:none"></canvas></div><div id="scan-summary"></div></div></section><section class="panel panel-pad"><div class="form-grid"><label class="field wide">الطالب<select id="scan-student" onchange="scanState.student=this.value;scanState.identityAutomatic=false;scanState.identityStatus='تم اختيار الطالب يدويًا';updateScanSummary()"><option value="">اختر الطالب</option>${options(db.students.map(st=>[st.id,st.number+' — '+st.name]),s.student)}</select></label><label class="field wide">نموذج الورقة<select aria-label="نموذج الورقة" onchange="changeScanVersion(Number(this.value))">${options([['8','الأفقي V8 — رقم الطالب وتنسيق الطباعة'],['7','الأفقي V7 — عناوين عند بداية كل نوع'],['6','الأفقي V6 — مجموع مقالي واحد وترقيم مستقل'],['5','الأفقي V5 — اختياري ثم صح وخطأ ثم مقالي'],['4','الأفقي V4 — معلومات بسطر وفقاعات المقال بالأعلى'],['3','الأفقي V3 — خط أكبر وثلاثة أعمدة'],['2','المضغوط V2 — ١٥ اختياري + ١٥ صح وخطأ'],['1','القديم V1 — ٨ أسئلة في الصفحة']],String(s.version||8))}</select></label><label class="field">رقم الصفحة<select aria-label="رقم الصفحة" onchange="scanState.p=Number(this.value);detectAndRead();renderScan()">${options(paperPlan(e,s.version||8).map((_,i)=>[String(i),'صفحة '+ar(i+1)]),String(s.p))}</select></label><label class="field">المحاذاة<input value="${s.corners?'مضبوطة — راجع بصريًا':'تحتاج ضبطًا يدويًا'}" readonly></label></div>${plan.items.map(v=>{const {q,i,bubbles}=v;return `<div class="review-q warn ${scanAnswerStatus(q,i,s)==='essay'?'':'state-card-'+scanAnswerStatus(q,i,s)}"><b>${i===-1?'مجموع المقالي':ar(questionNumber(e,i))+'. '+esc(q.text)}</b>${q.type!=='essay'?scanStatusTag(scanAnswerStatus(q,i,s)):''}${q.type==='essay'?essayScanControl(s,v):`<div class="row">${bubbles.map(b=>`<button title="${esc(q.options[b.value])}" class="bubble ${s.answers[i]===b.value?'selected state-mark-'+scanAnswerStatus(q,i,s):''}" onclick="scanState.answers[${i}]=${b.value};delete scanState.flags[${i}];delete scanState.readings[${i}];renderScan()">${b.label}</button>`).join('')}<button class="text-link" onclick="scanState.answers[${i}]=null;scanState.flags[${i}]='فارغ — ترك السؤال دون إجابة';scanState.readings[${i}]=[];renderScan()">فارغ</button><span style="margin-right:auto;font-size:10px;color:#749064">المفتاح: ${q.type==='tf'?(q.answer?'خ':'ص'):letters[q.answer]}</span></div>`}<p class="note">${esc(s.flags[i]||'راجع الإجابة')} ${s.readings?.[i]?'· قراءة: '+s.readings[i].map((n,j)=>(bubbles[j]?.label??ar(j))+': '+Math.round(n*100)+'٪').join('، '):''}</p></div>`}).join('')}<label class="switch-row note"><input id="confirm-review" type="checkbox">راجعت جميع إجابات هذه الصفحة ودرجاتها</label>${btn('✓ حفظ المراجعة والمتابعة','saveScan()')}<p class="note">الدرجة المقالية الفارغة أو المزدوجة تبقى غير مرصودة وتحتاج اختيار درجة قبل الحفظ. تُجمع صفحات الطالب في نتيجة واحدة.</p></section></div>`;$('#scan-img').onload=drawOverlay;drawOverlay();if(typeof updateScanSummary==='function')updateScanSummary()}
function changeScanVersion(v){if(!confirm('تغيير القالب يعيد قراءة الصفحة ويلغي التعديلات غير المحفوظة. متابعة؟'))return renderScan();scanState.version=v;scanState.p=0;detectAndRead();renderScan()}
function scanAnswerStatus(q,i,s){if(q.type==='essay')return'essay';const flag=String(s.flags?.[i]||''),scores=(s.readings?.[i]||[]).slice().sort((a,b)=>b-a);if(/تظليل متعدد|أكثر من درجة|ملتبس/.test(flag)||(scores[0]>.08&&scores[1]>.15&&scores[1]>scores[0]*.58))return'double';if(s.answers?.[i]!==null&&s.answers?.[i]!==undefined)return s.answers[i]===q.answer?'correct':'wrong';if(/فارغ|لم تُظلّل|لم تظلل/.test(flag))return'blank';return'unresolved'}
function resultAnswerStatus(r,q,i,p){if(!r.reviewed?.[i])return'unresolved';const saved=r.markings?.[p]?.[i]||Object.values(r.markings||{}).map(page=>page?.[i]).find(Boolean);if(saved?.status==='double')return'double';if(r.answers?.[i]!==null&&r.answers?.[i]!==undefined)return r.answers[i]===q.answer?'correct':'wrong';return saved?.status||'blank'}
const scanStatusNames={correct:'إجابة صحيحة',wrong:'إجابة خاطئة',double:'تظليل مزدوج',blank:'متروك',unresolved:'تحتاج مراجعة'};
const scanStatusColors={correct:'#18864b',wrong:'#d54747',double:'#e78a20',blank:'#2785c7',unresolved:'#a87931'};
function scanStatusTag(status){return `<span class="scan-status-tag state-${status}">${scanStatusNames[status]||scanStatusNames.unresolved}</span>`}
function scanStatusLegend(){return `<div class="scan-status-legend" aria-label="دليل ألوان الإجابات">${[['correct','صحيحة'],['wrong','خاطئة'],['double','مزدوجة'],['blank','متروكة']].map(([s,n])=>`<span><i class="state-${s}"></i>${n}</span>`).join('')}</div>`}
function scanMarkedValues(i,s,status){if(status==='double'){const values=(s.readings?.[i]||[]).map((n,j)=>({n,j})).filter(x=>x.n>.15).sort((a,b)=>b.n-a.n);return values.length>1?values.map(x=>x.j).slice(0,4):values.map(x=>x.j)}return s.answers?.[i]===null||s.answers?.[i]===undefined?[]:[s.answers[i]]}
function drawOverlay(){if(!scanState)return;const im=$('#scan-img'),c=$('#scan-overlay');if(!im||!c||!im.clientWidth)return;const s=scanState;c.width=im.clientWidth;c.height=im.clientHeight;if(!isManual&&!s.showOverlay)return;const ctx=c.getContext('2d'),scale=Math.min(im.clientWidth/s.canvas.width,im.clientHeight/s.canvas.height),ox=(im.clientWidth-s.canvas.width*scale)/2,oy=(im.clientHeight-s.canvas.height*scale)/2;ctx.strokeStyle=isManual?'#e77d37':'#52655c88';ctx.lineWidth=2;(isManual?manualCorners:s.corners||[]).forEach((p,i)=>{ctx.strokeRect(ox+p.x*scale-8,oy+p.y*scale-8,16,16);ctx.fillStyle='#e77d37';ctx.fillText(String(i+1),ox+p.x*scale+10,oy+p.y*scale)});if(s.corners&&!isManual&&s.showOverlay&&s.orientationReady!==false){try{const map=homography(s.corners,s.version||8);scanPlan(s,getExam()).items.forEach(v=>{if(v.q.type==='essay')return;const status=scanAnswerStatus(v.q,v.i,s),marked=scanMarkedValues(v.i,s,status);if(marked.length){for(const b of v.bubbles.filter(b=>marked.includes(b.value))){const bm=typeof bubblePointMap==='function'?bubblePointMap(s,map,v.i,b):map,p=bm(b.x,b.y),edge=bm(b.x+b.r,b.y),radius=Math.hypot(edge.x-p.x,edge.y-p.y)*scale;ctx.strokeStyle=scanStatusColors[status]||scanStatusColors.unresolved;ctx.lineWidth=2.5;ctx.beginPath();ctx.arc(ox+p.x*scale,oy+p.y*scale,radius+2,0,Math.PI*2);ctx.stroke()}}else if(status==='blank'){const p=map(v.x-8,v.y+8);ctx.strokeStyle=scanStatusColors.blank;ctx.lineWidth=2.5;ctx.beginPath();ctx.arc(ox+p.x*scale,oy+p.y*scale,7*scale,0,Math.PI*2);ctx.stroke()}})}catch{}}}
function drawResultOverlay(r,p){const im=$('#result-image'),c=$('#result-overlay');if(!im||!c||!im.complete||!im.naturalWidth)return;const w=im.clientWidth,h=im.clientHeight;if(!w||!h)return;c.width=w;c.height=h;const x=c.getContext('2d'),scale=Math.min(w/im.naturalWidth,h/im.naturalHeight),ox=(w-im.naturalWidth*scale)/2,oy=(h-im.naturalHeight*scale)/2,tmp=document.createElement('canvas');tmp.width=im.naturalWidth;tmp.height=im.naturalHeight;tmp.getContext('2d').drawImage(im,0,0);const corners=findMarkers(tmp);if(!corners)return;const version=r.snapshot?.paperVersion||1,e=resultExam(r),state={version,p,answers:r.answers,essay:r.essay,markings:r.markings?.[p]||{}},plan=scanPlan(state,e);try{const map=homography(corners,version),registration=typeof registerBubbleRings==='function'?registerBubbleRings(tmp,map,plan):null;state.bubbleRegistration=registration;plan.items.forEach(v=>{if(v.q.type==='essay')return;const status=resultAnswerStatus(r,v.q,v.i,p),saved=r.markings?.[p]?.[v.i],marked=saved?.marked||(r.answers?.[v.i]===null||r.answers?.[v.i]===undefined?[]:[r.answers[v.i]]);if(marked.length){for(const b of v.bubbles.filter(b=>marked.includes(b.value))){const bm=typeof bubblePointMap==='function'?bubblePointMap(state,map,v.i,b):map,pt=bm(b.x,b.y),edge=bm(b.x+b.r,b.y),radius=Math.hypot(edge.x-pt.x,edge.y-pt.y)*scale;x.strokeStyle=scanStatusColors[status]||scanStatusColors.unresolved;x.lineWidth=Math.max(2,im.naturalWidth/550);x.beginPath();x.arc(ox+pt.x*scale,oy+pt.y*scale,radius+2,0,Math.PI*2);x.stroke()}}else if(status==='blank'){const pt=map(v.x-8,v.y+8);x.strokeStyle=scanStatusColors.blank;x.lineWidth=Math.max(2,im.naturalWidth/550);x.beginPath();x.arc(ox+pt.x*scale,oy+pt.y*scale,7*scale,0,Math.PI*2);x.stroke()}})}catch{}}
function beginCorners(){isManual=true;manualCorners=[];$('#corner-hint').textContent='انقر مركز المربعات بالترتيب: أعلى اليسار ← أعلى اليمين ← أسفل اليمين ← أسفل اليسار';drawOverlay()}function pickCorner(ev){if(!isManual)return;const im=ev.currentTarget,r=im.getBoundingClientRect(),s=scanState,k=Math.min(r.width/s.canvas.width,r.height/s.canvas.height),ox=(r.width-s.canvas.width*k)/2,oy=(r.height-s.canvas.height*k)/2,x=(ev.clientX-r.left-ox)/k,y=(ev.clientY-r.top-oy)/k;if(x<0||y<0||x>s.canvas.width||y>s.canvas.height)return;manualCorners.push({x,y});drawOverlay();if(manualCorners.length===4){s.corners=manualCorners.slice();isManual=false;detectAndRead();renderScan();if(typeof identifyScanStudent==='function')identifyScanStudent(s)}else $('#corner-hint').textContent='تم تحديد '+ar(manualCorners.length)+' / ٤ — تابع بالترتيب المحدد'}
function rotateScan(){const s=scanState,c=document.createElement('canvas');c.width=s.canvas.height;c.height=s.canvas.width;const ctx=c.getContext('2d');ctx.translate(c.width,0);ctx.rotate(Math.PI/2);ctx.drawImage(s.canvas,0,0);s.canvas=c;s.url=c.toDataURL('image/jpeg',.93);s.corners=null;s.orientationReady=true;isManual=false;detectAndRead();renderScan();if(typeof identifyScanStudent==='function')identifyScanStudent(s)}async function cancelScan(){if(confirm('إلغاء مراجعة الملفات المتبقية؟')){const docs=new Set(scanQueue.map(item=>item.pdf?.doc).filter(Boolean));for(const doc of docs)try{await doc.destroy()}catch{}scanState=null;scanQueue=[];scanIndex=0;scan()}}
async function saveScan(){const s=scanState,e=getExam();if(!s.student)return toast('اختر الطالب أولًا');if(!$('#confirm-review').checked)return toast('راجع الإجابات ثم فعّل تأكيد المراجعة');const plan=scanPlan(s,e);if(plan.items.some(v=>v.q.type==='essay'&&(s.essay[v.i]===null||s.essay[v.i]===undefined||!Number.isFinite(s.essay[v.i])||s.essay[v.i]<0||s.essay[v.i]>v.q.points)))return toast('حدّد درجة المقالي المطلوبة قبل الحفظ. استخدم ٠ للدرجة الصفرية، ولا تتركها فارغة.');const st=db.students.find(x=>x.id===s.student);let r=db.results.find(r=>r.exam===e.id&&r.student===st.id);if(r&&r.pages[s.p]&&!confirm('هذه الصفحة محفوظة. هل تريد استبدالها؟'))return;try{if(!r){r={id:uid(),exam:e.id,student:st.id,name:st.name,number:st.number,group:st.group,snapshot:{...JSON.parse(JSON.stringify(e)),paperVersion:s.version||8},answers:{},essay:{},pages:{},reviewed:{},date:new Date().toISOString()}}else if(JSON.stringify(r.snapshot.questions)!==JSON.stringify(e.questions)||(r.snapshot.paperVersion||1)!==(s.version||8))return toast('تغير الاختبار بعد التصحيح. أنشئ اختبارًا منفصلًا للنسخة المعدلة.');const key=r.id+'-'+s.p+'-'+uid();await filePut(key,s.url);r.pages[s.p]=key;r.markings??={};r.markings[s.p]={};for(const {i,q} of plan.items){r.answers[i]=s.answers[i]??null;r.essay[i]=q.type==='essay'?s.essay[i]:0;r.reviewed[i]=true;if(q.type!=='essay'){const status=scanAnswerStatus(q,i,s);r.markings[s.p][i]={status,marked:scanMarkedValues(i,s,status)}}}if(s.version>=6)for(const v of paperPlan(e,s.version)[s.p].items)r.reviewed[v.i]=true;r.updated=new Date().toISOString();if(!db.results.some(x=>x.id===r.id))db.results.push(r);save();scanIndex++;if(scanIndex<scanQueue.length){await openScan();toast('حُفظت الصفحة. راجع الملف التالي.')}else{scanState=null;scanQueue=[];currentResult=r.id;location.hash='results';results();toast('تم حفظ النتائج والمراجعة')}}catch{toast('تعذر حفظ الصورة. تحقق من مساحة الجهاز وأعد المحاولة.')}}
function resultExam(r){return r.snapshot||db.exams.find(e=>e.id===r.exam)}
score=function(r){const e=resultExam(r);if(!e)return 0;return (r.snapshot?.paperVersion>=6?Math.min(essayMaximum(e),Math.max(0,Number(r.essay?.[-1]||0))):0)+e.questions.reduce((a,q,i)=>a+(q.type==='essay'?(r.snapshot?.paperVersion>=6?0:Math.min(q.points,Math.max(0,Number(r.essay?.[i]||0)))):(q.answer!==null&&r.answers[i]===q.answer?Number(q.points):0)),0)};
function results(){if(currentResult&&db.results.some(r=>r.id===currentResult))return reviewResult(currentResult);$('#app').innerHTML=head('النتائج والتقارير','الورقة الأصلية، الإجابات، والدرجة. كل شيء قابل للمراجعة.',btn('↓ تصدير CSV','exportResults()','light'))+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>رقم الطالب</th><th>الطالب</th><th>الاختبار</th><th>الدرجة</th><th>الحالة</th><th>الورقة</th></tr></thead><tbody>${db.results.slice().reverse().map(r=>{const e=resultExam(r),complete=Object.keys(r.pages).length>=resultPageCount(r);return `<tr><td><strong>${esc(r.number)}</strong></td><td><span class="avatar">${esc(r.name[0])}</span>${esc(r.name)}</td><td>${esc(e.title)}</td><td><strong>${ar(score(r))}</strong> / ${ar(total(e))}</td><td><span class="tag ${complete?'':'amber'}">${complete?'راجَعها المعلم':'صفحات ناقصة'}</span></td><td><button class="text-link" onclick="reviewResult('${r.id}')">معاينة وتعديل ←</button></td></tr>`}).join('')}</tbody></table></div>${!db.results.length?empty('نتائج تستحق الاحتفاء','ابدأ برفع أول ورقة في قسم التصحيح.',`<a class="btn light small" href="#scan">الانتقال للتصحيح</a>`):''}</section>`}
async function reviewResult(id,p=0){const r=db.results.find(r=>r.id===id);if(!r)return;currentResult=id;const e=resultExam(r);if(!r.pages[p])p=Number(Object.keys(r.pages)[0]);$('#app').innerHTML=head(r.name,`${e.title} · ${r.number} · ${r.group}`,btn('كل النتائج','currentResult=null;results()','light')+btn('حذف النتيجة',`deleteResult('${id}')`,'danger small'))+`<div class="review-layout"><section class="panel panel-pad"><div class="toolbar"><select onchange="reviewResult('${id}',Number(this.value))">${options(Object.keys(r.pages).map(p=>[p,'صفحة '+ar(Number(p)+1)]),String(p))}</select></div><div class="result-page-image-wrap"><img id="result-image" class="scan-preview" alt="صورة ورقة الطالب الأصلية"><canvas id="result-overlay" aria-hidden="true"></canvas></div>${scanStatusLegend()}<p class="note">الصورة الأصلية محفوظة على هذا الجهاز. تعديل الإجابات يحدّث النتيجة مباشرة.</p></section><section class="panel panel-pad"><div class="result-score"><div><h3>الدرجة الحالية</h3><p class="note">${Object.keys(r.pages).length} / ${resultPageCount(r)} صفحات محفوظة</p></div><div><span class="score">${ar(score(r))}</span><span class="note"> / ${ar(total(e))}</span></div></div>${r.snapshot?.paperVersion>=6&&essayMaximum(e)?`<div class="review-q"><b>مجموع درجات المقالي</b><input type="number" min="0" max="${essayMaximum(e)}" step="1" value="${r.essay[-1]??''}" onchange="editResult('${id}',-1,this.value,true,${p})"><span> / ${ar(essayMaximum(e))}</span></div>`:''}${e.questions.map((q,i)=>`<div class="review-q ${q.type==='essay'?'':'state-card-'+resultAnswerStatus(r,q,i,p)}"><b>${ar(questionNumber(e,i))}. ${esc(q.text)}</b>${q.type!=='essay'?scanStatusTag(resultAnswerStatus(r,q,i,p)):''}<div class="row">${q.type==='essay'?(r.snapshot?.paperVersion>=6?'<span class="note">ضمن مجموع المقالي الموحد</span>':`<label>الدرجة من ${ar(q.points)} <input style="width:85px" type="number" min="0" max="${q.points}" step="1" value="${r.essay[i]??''}" onchange="editResult('${id}',${i},this.value,true,${p})"></label>`):q.options.map((o,j)=>`<button title="${esc(o)}" class="bubble ${r.answers[i]===j?'selected state-mark-'+resultAnswerStatus(r,q,i,p):''}" onclick="editResult('${id}',${i},${j},false,${p})">${q.type==='tf'?(j?'خ':'ص'):letters[j]}</button>`).join('')+`<button class="text-link" onclick="editResult('${id}',${i},null,false,${p})">فارغ</button><span class="tag ${r.answers[i]===q.answer?'':'amber'}" style="margin-right:auto">${r.answers[i]===q.answer?'صحيحة':r.answers[i]==null?'فارغة':'غير صحيحة'}</span>`}</div>${!r.reviewed[i]?'<p class="note">لم تُرفع صفحة هذا السؤال بعد</p>':''}</div>`).join('')}<p class="note">آخر تعديل: ${new Date(r.updated||r.date).toLocaleString('ar-SA')}<br>تعتمد هذه النتيجة على نسخة مفتاح الإجابة وقت التصحيح.</p></section></div>`;try{const url=await fileGet(r.pages[p]);if($('#result-image')){if(url){const image=$('#result-image');image.onload=()=>drawResultOverlay(r,p);image.src=url;if(image.complete)drawResultOverlay(r,p)}else $('#result-image').alt='صورة الورقة غير متاحة؛ راجع النسخة الاحتياطية الأصلية'}}catch{toast('تعذر استرجاع الورقة')}}
function editResult(id,i,v,essay,p){const r=db.results.find(r=>r.id===id),q=i===-1?{points:essayMaximum(resultExam(r))}:resultExam(r).questions[i];if(essay){if(v===''||!Number.isInteger(Number(v))||Number(v)<0||Number(v)>q.points)return toast('أدخل درجة صحيحة من ٠ إلى '+ar(q.points));r.essay[i]=Number(v)}else{r.answers[i]=v;r.markings??={};r.markings[p]??={};r.markings[p][i]={status:v===null?'blank':v===q.answer?'correct':'wrong',marked:v===null?[]:[Number(v)]}}r.updated=new Date().toISOString();save();reviewResult(id,p)}function deleteResult(id){if(!confirm('حذف النتيجة؟'))return;db.results=db.results.filter(r=>r.id!==id);currentResult=null;save();results()}
function download(name,data,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000)}
function csvValue(v){let t=String(v??'');if(/^[=+\-@]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'}function exportResults(){if(!db.results.length)return toast('لا توجد نتائج للتصدير');const rows=[['الاسم','الرقم','المجموعة','الاختبار','الدرجة','المجموع','الصفحات','آخر تعديل'],...db.results.map(r=>[r.name,r.number,r.group,resultExam(r).title,score(r),total(resultExam(r)),Object.keys(r.pages).length,r.updated||r.date])];download('waraqa-results.csv','\uFEFF'+rows.map(row=>row.map(csvValue).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
async function backup(){try{toast('جارٍ إعداد النسخة الاحتياطية…');const files={};for(const r of db.results)for(const k of Object.values(r.pages))files[k]=await fileGet(k);download('waraqa-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({version:1,db,files}),'application/json');toast('تم تجهيز النسخة مع صور الأوراق')}catch{toast('تعذر إنشاء النسخة الاحتياطية')}}
async function restore(file){if(!file)return;try{const b=JSON.parse(await file.text());if(b.version!==1||!b.db||!['students','groups','exams','results'].every(k=>Array.isArray(b.db[k]))||b.db.exams.some(e=>!Array.isArray(e.questions)))throw Error();if(!confirm('استبدال البيانات الحالية بالنسخة الاحتياطية؟ صدّر بياناتك الحالية أولًا إن أردت الاحتفاظ بها.'))return;for(const [k,v]of Object.entries(b.files||{})){if(typeof v==='string'&&/^data:image\/(jpeg|png|webp);base64,/.test(v))await filePut(k,v)}db=b.db;save();currentExam=null;currentResult=null;scanState=null;render();toast('تمت استعادة النسخة')}catch{toast('ملف النسخة غير صالح أو تعذرت استعادته')}}
function help(){modal('دليلك إلى ورقة',`<p class="sub">١. أضف الطلاب والمجموعات.<br>٢. أنشئ الاختبار وأسئلته وحدّد مفتاح الإجابة والدرجات.<br>٣. اطبع نموذج ورقة A4 بالاتجاه الأفقي والحجم الفعلي.<br>٤. ارفع صور الأوراق أو PDF أو التقط صورة بكاميرا الهاتف.<br>٥. اربط الصفحة بالطالب، وراجع محاذاة الزوايا والإجابات.<br>٦. احفظ النتيجة وعدّلها أو صدّرها وقت الحاجة.</p><div class="callout" style="margin-top:20px">القراءة التجريبية للتظليل تعتمد على نموذج ورقة المطبوع. يصحّح المعلم المقال يدويًا ويظلّل مجموع درجات المقاليات مرة واحدة (١–١٥؛ الصفر والمجموع الأعلى يُرصدان يدويًا)، ثم تُقرأ الدرجة وتُجمع مع بقية الأسئلة. لا تتضمن التعرّف على النصوص أو تقييم النص المقالي آليًا. كل ورقة تحتاج مراجعة المعلم. البيانات والصور مرتبطة بحساب ChatGPT وتُزامن بين أجهزتك. انتظر ظهور «محفوظ في حسابك» قبل الانتقال. انقل البيانات القديمة من المتصفح الأصلي مرة واحدة، واحتفظ بنسخة احتياطية.</div>`)}
window.addEventListener('hashchange',route);window.addEventListener('resize',drawOverlay);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});/* cloud.js initializes after authenticated account data is loaded. */
